package local.proskurnin.preview;
import android.content.*;import android.graphics.*;import java.util.*;import java.text.*;import org.json.*;
final class CurrencyWidget {
 static ArrayList<String> rows(MainActivity a){return CurrencyConfig.parse(a.prefs.getString("currency_rows",CurrencyConfig.DEFAULT));}
 static void save(MainActivity a,ArrayList<String> rows){a.prefs.edit().putString("currency_rows",android.text.TextUtils.join(",",rows)).apply();a.ratesAttempt=-1;a.fetchRates();a.screen.invalidate();}
 static void menu(MainActivity a){ArrayList<String> r=rows(a),names=new ArrayList<>();names.add("Виджет: "+(a.prefs.getBoolean("currency_enabled",true)?"вкл":"выкл"));for(String p:r)names.add(p.replace(":"," → "));names.add("Добавить валюту · "+r.size()+"/4");names.add("Недельные графики: "+(a.prefs.getBoolean("rates_chart",true)?"вкл":"выкл"));names.add("Сбросить к USD / EUR / CNY / BTC");new LauncherDialogs.Builder(a).setTitle("Виджет валют").setItems(names.toArray(new String[0]),(d,n)->{if(n==0){a.prefs.edit().putBoolean("currency_enabled",!a.prefs.getBoolean("currency_enabled",true)).apply();save(a,r);menu(a);}else if(n<=r.size())edit(a,n-1);else if(n==r.size()+1){if(r.size()<4)pickBase(a,-1);else android.widget.Toast.makeText(a,"Сначала удалите одну строку",0).show();}else if(n==r.size()+2){a.prefs.edit().putBoolean("rates_chart",!a.prefs.getBoolean("rates_chart",true)).apply();save(a,r);menu(a);}else{a.prefs.edit().putBoolean("currency_enabled",true).putBoolean("rates_chart",true).apply();save(a,CurrencyConfig.parse(null));menu(a);}}).setNegativeButton("Закрыть",null).show();}
 static void edit(MainActivity a,int index){ArrayList<String> r=rows(a);if(index>=r.size())return;new LauncherDialogs.Builder(a).setTitle(r.get(index).replace(":"," → ")).setItems(new String[]{"Заменить валюту","Валюта котировки","Выше","Ниже","Убрать строку"},(d,n)->{if(n==0){pickBase(a,index);return;}if(n==1){pickQuote(a,index,r.get(index).split(":")[0]);return;}if(n==2&&index>0)Collections.swap(r,index,index-1);if(n==3&&index+1<r.size())Collections.swap(r,index,index+1);if(n==4)r.remove(index);save(a,r);menu(a);}).setNegativeButton("Назад",(d,n)->menu(a)).show();}
 static void pickBase(MainActivity a,int index){new LauncherDialogs.Builder(a).setTitle("Валюта / криптовалюта").setItems(CurrencyConfig.BASES,(d,n)->pickQuote(a,index,CurrencyConfig.BASES[n])).setNegativeButton("Отмена",(d,n)->menu(a)).show();}
 static void pickQuote(MainActivity a,int index,String base){ArrayList<String> q=new ArrayList<>();for(String s:CurrencyConfig.QUOTES)if(!s.equals(base))q.add(s);new LauncherDialogs.Builder(a).setTitle("Цена "+base+" в валюте").setItems(q.toArray(new String[0]),(d,n)->{ArrayList<String> r=rows(a);String pair=base+":"+q.get(n);if(r.contains(pair)&&(index<0||!pair.equals(r.get(index)))){android.widget.Toast.makeText(a,"Эта пара уже добавлена",0).show();return;}if(index<0){if(r.size()<4)r.add(pair);}else if(index<r.size())r.set(index,pair);save(a,r);menu(a);}).setNegativeButton("Отмена",(d,n)->menu(a)).show();}
 static String day(long t){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date(t));}
 static double number(android.content.SharedPreferences p,String k){try{return RatesClient.positive(Double.parseDouble(p.getString(k,"")));}catch(Exception e){return Double.NaN;}}
 static void migrate(MainActivity a,String pair){String[] v=pair.split(":");int i=Arrays.asList("USD","EUR","CNY").indexOf(v[0]);boolean fiat=i>=0&&v[1].equals("RUB"),btc=pair.equals("BTC:USD");if(!fiat&&!btc)return;String source=fiat&&a.prefs.getString("fiat_date","").startsWith("ЦБ")?"CBR":"Coinbase",k=CurrencyConfig.key(pair,source),old=btc?"BTC_USD":v[0];if(a.prefs.contains(k+"_at"))return;long at=a.prefs.getLong(btc?"btc_usd_at":"fiat_at",0);double value=number(a.prefs,old);if(at<=0||!Double.isFinite(value))return;android.content.SharedPreferences.Editor e=a.prefs.edit().putString(k,String.valueOf(value)).putLong(k+"_at",at).putString("cw_source_"+pair,source);for(int n=1;n<=7;n++){String d=day(System.currentTimeMillis()-n*86400000L),ok="history_"+old+"_"+source+"_"+d;if(a.prefs.contains(ok))e.putString(k+"_"+d,a.prefs.getString(ok,""));}e.apply();}
 static boolean running(MainActivity a){return a.active&&a.prefs.getBoolean("currency_enabled",true);}
 static void fetch(MainActivity a){if(!running(a))return;long now=System.currentTimeMillis();Map<String,String[]> cbrHistory=new HashMap<>();String[] fiat=null;boolean fiatTried=false;
  for(String pair:rows(a)){if(!running(a))return;migrate(a,pair);String[] v=pair.split(":");String source=a.prefs.getString("cw_source_"+pair,"Coinbase"),k=CurrencyConfig.key(pair,source);long at=a.prefs.getLong(k+"_at",0);boolean defaultFiat=v[1].equals("RUB")&&Arrays.asList("USD","EUR","CNY").contains(v[0]);long interval=defaultFiat?21600000:300000;
   if(now<at||now-at>interval){try{double value;if(defaultFiat){if(!fiatTried){fiatTried=true;fiat=RatesClient.fiat();}if(fiat==null)throw new Exception("unavailable");value=RatesClient.positive(Double.parseDouble(fiat[Arrays.asList("USD","EUR","CNY").indexOf(v[0])]));source=fiat[3].startsWith("ЦБ")?"CBR":"Coinbase";}else{JSONObject d=WeatherClient.json("https://api.coinbase.com/v2/exchange-rates?currency="+v[0]).getJSONObject("data");if(!v[0].equals(d.getString("currency")))throw new Exception("pair");value=RatesClient.positive(d.getJSONObject("rates").getDouble(v[1]));source="Coinbase";}k=CurrencyConfig.key(pair,source);a.prefs.edit().putString(k,String.valueOf(value)).putLong(k+"_at",now).putString("cw_source_"+pair,source).putBoolean(k+"_error",false).apply();}catch(Exception e){a.prefs.edit().putBoolean(k+"_error",true).apply();}}
   int days=a.prefs.getBoolean("rates_chart",true)?6:1;for(int n=1;n<=days&&running(a);n++){String d=day(now-n*86400000L),hk=k+"_"+d;if(a.prefs.contains(hk)||now-a.prefs.getLong(hk+"_try",0)<1800000)continue;a.prefs.edit().putLong(hk+"_try",now).apply();try{double value;if(source.equals("CBR")){String[] data=cbrHistory.get(d);if(data==null){String[] date=d.split("-");data=RatesClient.cbr("?date_req="+date[2]+"/"+date[1]+"/"+date[0]);cbrHistory.put(d,data);}value=Double.parseDouble(data[Arrays.asList("USD","EUR","CNY").indexOf(v[0])]);}else{JSONObject data=WeatherClient.json("https://api.coinbase.com/v2/prices/"+v[0]+"-"+v[1]+"/spot?date="+d).getJSONObject("data");if(!v[0].equals(data.getString("base"))||!v[1].equals(data.getString("currency")))throw new Exception("pair");value=data.getDouble("amount");}a.prefs.edit().putString(hk,String.valueOf(RatesClient.positive(value))).apply();}catch(Exception ignored){}}
  }
  String cutoff=day(now-8*86400000L);android.content.SharedPreferences.Editor clean=a.prefs.edit();for(String k:a.prefs.getAll().keySet())if(k.startsWith("cw_")){java.util.regex.Matcher m=java.util.regex.Pattern.compile("_(\\d{4}-\\d{2}-\\d{2})(?:_try)?$").matcher(k);if(m.find()&&m.group(1).compareTo(cutoff)<0)clean.remove(k);}clean.apply();
 }
 static void draw(MainActivity a,Canvas c){if(!a.prefs.getBoolean("currency_enabled",true))return;ArrayList<String> rows=rows(a);MainActivity.Screen s=a.screen;Paint p=s.p;long now=System.currentTimeMillis();for(int i=0;i<rows.size();i++){String pair=rows.get(i);String[] v=pair.split(":");String source=a.prefs.getString("cw_source_"+pair,"Coinbase"),k=CurrencyConfig.key(pair,source);float y=274+(4-rows.size())*87+i*87;p.setStyle(Paint.Style.FILL);p.setColor(MainActivity.PANEL_BACKGROUND);c.drawRoundRect(new RectF(1210,y,1797,y+76),18,18,p);p.setColor(0xbf4e6a89);c.drawCircle(1252,y+38,25,p);p.setTextAlign(Paint.Align.CENTER);String symbol=CurrencyConfig.symbol(v[0]);s.text(c,symbol,1252,y+49,symbol.length()>1?18:30,0xffdae8ff,s.medium);p.setTextAlign(Paint.Align.LEFT);s.text(c,v[0],1295,y+32,25,0xffe1e6ef,s.medium);long at=a.prefs.getLong(k+"_at",0),age=now-at;double value=number(a.prefs,k);boolean valid=at>0&&age>=0&&age<86400000L*7;String label=(source.equals("CBR")?"ЦБ":source)+" · "+v[1];if(at==0)label="Нет данных · "+v[1];else if(a.prefs.getBoolean(k+"_error",false)||age>21600000)label+=" · кэш";s.text(c,label,1295,y+58,16,0xffa8b5c8,s.light);
   double[] history=new double[7];for(int j=0;j<6;j++)history[j]=number(a.prefs,k+"_"+day(now-(6-j)*86400000L));history[6]=valid?value:Double.NaN;float[] points=RatesSparkline.normalize(history);if(a.prefs.getBoolean("rates_chart",true)&&points!=null){int first=0,last=6;while(!Double.isFinite(history[first]))first++;while(!Double.isFinite(history[last]))last--;p.setColor(history[last]>history[first]?0xff9cdeb5:history[last]<history[first]?0xffff929c:0xffa8b5c8);p.setStrokeWidth(2.5f);for(int j=0;j<7;j++){if(!Float.isFinite(points[j]))continue;float x=1498+j*17,yy=y+15+points[j]*40;if(j>0&&Float.isFinite(points[j-1]))c.drawLine(x-17,y+15+points[j-1]*40,x,yy,p);c.drawCircle(x,yy,2,p);}}
   String quote=CurrencyConfig.symbol(v[1]),price=valid&&Double.isFinite(value)?new DecimalFormat(value>=10000?"#,##0":value<1?"0.0000":"0.00",DecimalFormatSymbols.getInstance(new Locale("ru"))).format(value)+" "+quote:"—";p.setTextAlign(Paint.Align.RIGHT);p.setTextSize(34);p.setTypeface(s.light);float size=Math.min(34,34*163/Math.max(1,p.measureText(price)));s.text(c,price,1772,y+33,(int)size,Color.WHITE,s.light);double delta=valid?RatesTrend.absolute(value,history[5]):Double.NaN;s.text(c,CurrencyConfig.delta(delta,value,quote),1772,y+58,16,CurrencyConfig.neutral(delta,value)?0xffa8b5c8:delta>0?0xff9cdeb5:0xffff929c,s.light);p.setTextAlign(Paint.Align.LEFT);
  }if(!rows.isEmpty())s.text(c,"Изменение к предыдущему дню (UTC)",1215,646,MainActivity.CAPTION_SIZE,0xff9aa9be,s.light);
 }
}
